@app.before_request
def authenticate():
    if request.endpoint in ["signup", "login", "refresh_access", "refresh_refresh"]:
        return
    auth_header = request.headers.get("Authorization")
    if not auth_header or not auth_header.startswith("Bearer "):
        return {"error": "Unauthorized", "message": "Bearer token required"}, 401
    token = auth_header.split(" ")[1]
    try:
        g.user_uuid = jwt_provider.validate_access_token(token)
    except JwtError as e:
        return {"error": "Unauthorized", "message": str(e)}, 401
